        dc=(o[1]-start[1])/abs(o[1]-start[1]) if o[1]!=start[1] else 0
    dr=int(round(dr)); dc=int(round(dc))
    cur=start; d=(dr,dc)
    while True:
        nr,nc=cur[0]+d[0],cur[1]+d[1]
        if not(0<=nr<H and 0<=nc<W): break
